        corporation_tax_rate: 0.05,
        standing_level: 'terrible',
        terrible_standing_tax_rate: 0.5,
      },
      {
        office_id: 7002,
        system_id: 30000143,
        planet_id: 40000010,
        reinforce_exit_start: 0,
        reinforce_exit_end: 3,
        alliance_tax_rate: 0.1,
        corporation_tax_rate: 0.05,
        standing_level: 'neutral',
        terrible_standing_tax_rate: 0.5,
